// DecodeReadItemEditSourceRequest returns a decoder for requests sent to the
// WorkItemTypes ReadItemEditSource endpoint.
func DecodeReadItemEditSourceRequest(mux loomhttp.Muxer, _ func(*http.Request) loomhttp.Decoder) func(*http.Request) (*workitemtypes.ReadItemEditSourcePayload, error) {
	return func(r *http.Request) (*workitemtypes.ReadItemEditSourcePayload, error) {
		var payload *workitemtypes.ReadItemEditSourcePayload
		var err error
		var (
			slug      string
			mode      string
			itemID    string
			projectID *string

			params = mux.Vars(r)
		)
		slug = params["slug"]
		if utf8.RuneCountInString(slug) < 1 {
			err = loom.MergeErrors(err, loom.InvalidLengthError("slug", utf8.RuneCountInString(slug), 1, true))
		}
		if utf8.RuneCountInString(slug) > 255 {
			err = loom.MergeErrors(err, loom.InvalidLengthError("slug", utf8.RuneCountInString(slug), 255, false))
		}
		qp, queryErr := url.ParseQuery(r.URL.RawQuery)
		if queryErr != nil {
			return payload, loom.DecodePayloadError("invalid query string")
		}
		{
			modeRaw := qp.Get("mode")
			modePresent := qp.Has("mode")

			if modePresent {
				mode = modeRaw
				if !(mode == "edit" || mode == "draft") {
					err = loom.MergeErrors(err, loom.InvalidEnumValueError("mode", mode, []any{"edit", "draft"}))
				}
			} else {
				err = loom.MergeErrors(err, loom.MissingFieldError("mode", "query string"))
			}
		}
		{
			itemIDRaw := qp.Get("item_id")
			itemIDPresent := qp.Has("item_id")

			if itemIDPresent {
				itemID = itemIDRaw
				err = loom.MergeErrors(err, loom.ValidateFormat("item_id", itemID, loom.FormatUUID))
			} else {
				err = loom.MergeErrors(err, loom.MissingFieldError("item_id", "query string"))
			}
		}
		{
			projectIDRaw := qp.Get("project_id")
			projectIDPresent := qp.Has("project_id")

			if projectIDPresent {
				projectID = &projectIDRaw
				if projectID != nil {
					err = loom.MergeErrors(err, loom.ValidateFormat("project_id", *projectID, loom.FormatUUID))
				}
			}
		}
		if err != nil {
			return payload, err
		}
		payload = NewReadItemEditSourcePayload(slug, mode, itemID, projectID)

		return payload, nil
	}
}

